-- ==========================================================================
-- B4 FOLLOW-ON FIX (welltest): welltest: one partly-valid distractor sharpened into a clearly wrong one
--
-- Courses: welltest. Rows changed: 1; rows inserted: 0.
-- Source: tools/answer-length-audit/fixes/welltest.json (every item, its verdict and
-- its reason, old and new text side by side); generated by
-- tools/answer-length-audit/fix.py sql welltest. Runs AFTER the 29 B4 length files
-- and any earlier fix file: every guard below is the text those leave behind.
--
-- GUARDS. Each changed row must match its OLD prompt, explanation and options
-- (md5) and answer_index exactly (then it is updated) or its NEW ones (already
-- applied, left alone). Anything else raises and the transaction rolls back.
-- Each insert must be absent (inserted) or present with the same text (left).
-- Each course ends at its asserted question count. SAFE TO RE-RUN.
-- ==========================================================================

do $$
declare
  v_state   text;
  v_count   integer;
  v_updated integer := 0;
  v_total   integer;
begin

  -- welltest advanced module m04-gas ord 15
  select case when md5(prompt) = '98f4d0c98a4a4749e9f21d95b592457e' and md5(coalesce(explanation, '')) = 'c52a815b213b20973de167839991486b' and md5(options::text) = md5('["Because the absolute open flow is an extrapolation to nearly twice the largest tested value.", "Because the back-pressure fit uses logarithms and the LIT fit does not, so they weight the points differently.", "Because the three points are too few to determine two parameters plus an exponent reliably in either fit.", "Because the LIT form ignores the base pressure, which the back-pressure form includes."]'::jsonb::text) and answer_index = 0 then 'old'
              when md5(prompt) = '98f4d0c98a4a4749e9f21d95b592457e' and md5(coalesce(explanation, '')) = 'c52a815b213b20973de167839991486b' and md5(options::text) = md5('["Because the absolute open flow is an extrapolation to nearly twice the largest tested value.", "Because the back-pressure fit uses logarithms and the LIT fit does not, so they weight the points differently.", "Because three points leave the back-pressure fit underdetermined, so its exponent is only loosely fixed by the data.", "Because the LIT form ignores the base pressure, which the back-pressure form includes."]'::jsonb::text) and answer_index = 0 then 'new'
              else 'other' end
    into v_state
    from public.academy_quiz_questions where app_slug = 'welltest' and tier = 'advanced' and scope = 'module' and module_key is not distinct from 'm04-gas' and ord = 15 and active;
  if v_state is null then raise exception 'B4 fix welltest refused: no row for welltest advanced module m04-gas ord 15'; end if;
  if v_state = 'other' then raise exception 'B4 fix welltest refused: welltest advanced module m04-gas ord 15 matches neither its current nor its fixed form'; end if;
  if v_state = 'old' then
    update public.academy_quiz_questions set prompt = 'The two deliverability methods disagree by about four percent on the same three points. Why?', options = '["Because the absolute open flow is an extrapolation to nearly twice the largest tested value.", "Because the back-pressure fit uses logarithms and the LIT fit does not, so they weight the points differently.", "Because three points leave the back-pressure fit underdetermined, so its exponent is only loosely fixed by the data.", "Because the LIT form ignores the base pressure, which the back-pressure form includes."]'::jsonb,
           answer_index = 0, explanation = 'Nothing in either fit constrains behaviour outside the tested range, and the fit statistic cannot report on a region it never saw. The one with the better r squared returns the larger number.'
     where app_slug = 'welltest' and tier = 'advanced' and scope = 'module' and module_key is not distinct from 'm04-gas' and ord = 15 and active;
    get diagnostics v_count = row_count;
    if v_count <> 1 then raise exception 'B4 fix welltest refused: welltest advanced module m04-gas ord 15 updated % rows', v_count; end if;
    v_updated := v_updated + 1;
  end if;

  select count(*) into v_total from public.academy_quiz_questions where app_slug = 'welltest' and active;
  if v_total <> 396 then raise exception 'B4 fix welltest refused: welltest holds % active questions, expected 396', v_total; end if;
  raise notice 'B4 fix welltest: % of 1 rows written, the rest already carried the fixed text', v_updated;
end $$;
